// Generated by AI (UnitTest MCP)
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { test } from 'node:test';
import { createContext, SourceTextModule, SyntheticModule } from 'node:vm';

const k6Root = new URL('../k6/', import.meta.url);

function workerProfile(overrides = {}) {
  return {
    run_id: 'test-run',
    run_name: 'test',
    target_rps: 5000,
    ramp_up_seconds: 0,
    duration_seconds: 60,
    ramp_down_seconds: 0,
    pattern: 'keepalive-burst',
    endpoints: [{ id: 'ping', method: 'GET', url: 'https://load-target.invalid/ping', weight: 1 }],
    ...overrides,
  };
}

async function loadK6(relativePath, { profile = {}, random = Math.random } = {}) {
  const calls = [];
  const response = { status: 200 };
  const math = Object.create(Math);
  math.random = random;
  const context = createContext({ open: () => JSON.stringify(profile), Math: math });
  const http = new SyntheticModule(['default'], function () {
    this.setExport('default', {
      request(...args) {
        calls.push(args);
        return response;
      },
    });
  }, { context });
  const modules = new Map();
  function sourceModule(url) {
    if (!url.href.startsWith(k6Root.href)) {
      throw new Error('Test module escaped the k6 source directory');
    }
    if (!modules.has(url.href)) {
      modules.set(url.href, new SourceTextModule(readFileSync(url, 'utf8'), {
        identifier: url.href,
        context,
      }));
    }
    return modules.get(url.href);
  }
  const entry = sourceModule(new URL(relativePath, k6Root));
  await entry.link((specifier, referencingModule) => {
    if (specifier === 'k6/http') return http;
    return sourceModule(new URL(specifier, referencingModule.identifier));
  });
  await entry.evaluate();
  return { exports: entry.namespace, calls, response };
}

test('transport dispatches every supported method through k6 request', async () => {
  const { exports, calls, response } = await loadK6('lib/transport.js');
  for (const method of ['GET', 'HEAD', 'DELETE', 'post', 'PUT', 'PATCH']) {
    const endpoint = { method, url: 'https://load-target.invalid/resource' };
    const params = { tags: { endpoint: 'resource' } };
    const body = ['post', 'PUT', 'PATCH'].includes(method) ? '{"payload":"ok"}' : null;
    assert.equal(exports.sendRequest(endpoint, params, body), response);
    assert.deepEqual(calls.at(-1), [method.toUpperCase(), endpoint.url, body, params]);
  }
});

test('payload construction respects configured sizes and does not add GET bodies', async () => {
  const { exports } = await loadK6('lib/transport.js');
  const payloads = exports.buildPayloads([
    { id: 'read', method: 'GET', body_bytes: 4096 },
    { id: 'write', method: 'POST', body_bytes: 32768 },
    { id: 'default', method: 'PATCH' },
  ], 512);
  assert.equal(payloads.read, null);
  assert.equal(payloads.write.length, 32768);
  assert.equal(payloads.default.length, 512);
  assert.equal(JSON.parse(payloads.write).seq, 0);
});

test('synthetic JSON remains valid at small and large payload sizes', async () => {
  const { exports } = await loadK6('lib/transport.js');
  for (const size of [1, 512, 32768, 1024 * 1024]) {
    const payload = exports.syntheticJSON(size);
    assert.equal(payload.length, Math.max(size, '{"payload":"a","seq":0}'.length));
    assert.equal(JSON.parse(payload).seq, 0);
  }
});

test('single-endpoint picker bypasses random sampling', async () => {
  const { exports } = await loadK6('lib/profile.js', {
    profile: workerProfile(),
    random: () => { throw new Error('single endpoint must not sample randomness'); },
  });
  const endpoint = { id: 'only', weight: 1 };
  const pick = exports.buildWeightedPicker([endpoint]);
  assert.equal(pick(), endpoint);
  assert.equal(pick(), endpoint);
});

test('weighted picker handles finite weights that would otherwise overflow', async () => {
  const { exports } = await loadK6('lib/profile.js', {
    profile: workerProfile(),
    random: () => 0.25,
  });
  const first = { id: 'first', weight: 1e308 };
  const second = { id: 'second', weight: 1e308 };
  assert.equal(exports.buildWeightedPicker([first, second])(), first);
});

test('weighted picker rejects invalid weights before traffic starts', async () => {
  const { exports } = await loadK6('lib/profile.js', { profile: workerProfile() });
  for (const weight of [0, -1, NaN, Infinity]) {
    assert.throws(() => exports.buildWeightedPicker([{ id: 'invalid', weight }]), /finite and positive/);
  }
  assert.throws(() => exports.buildWeightedPicker([]), /at least one/);
});

test('runner configures connection reuse globally for each traffic pattern', async () => {
  for (const pattern of ['keepalive-burst', 'new-conn-flood']) {
    const profile = workerProfile({ pattern });
    const { exports, calls } = await loadK6('runner.js', { profile });
    assert.equal(exports.options.noConnectionReuse, pattern === 'new-conn-flood');
    exports.default();
    assert.equal(calls.length, 1);
    assert.equal(calls[0][0], 'GET');
    assert.equal(calls[0][1], profile.endpoints[0].url);
    assert.equal('noConnectionReuse' in calls[0][3], false);
    assert.ok(exports.options.scenarios[pattern].maxVUs >= exports.options.scenarios[pattern].preAllocatedVUs);
  }
});

test('standalone new-connection scenario also disables reuse globally', async () => {
  const { exports } = await loadK6('scenarios/new-conn-flood.js', {
    profile: workerProfile({ pattern: 'new-conn-flood' }),
  });
  assert.equal(exports.options.noConnectionReuse, true);
});